        [0, 1, 2, 3]

    See also :func:`collapse`, which can flatten multiple levels of nesting.

    """
    for sublist in list_of_lists:
        for item in sublist:
            yield item

import math

def dotproduct(vec1, vec2):
    """Returns the dot product of the two iterables.

    >>> dotproduct([10, 15, 12], [0.65, 0.80, 1.25])
    33.5
    >>> 10 * 0.65 + 15 * 0.80 + 12 * 1.25
    33.5

    In Python 3.12 and later, use ``math.sumprod()`` instead.
    """
    if math.version >= '3.12':
        return math.sumprod(zip(vec1, vec2))
    else:
        return sum(x * y for x, y in zip(vec1, vec2))

from itertools import islice, tee

def duplicates_justseen(iterable, key=None):
    """Yields serially-duplicate elements after their first appearance.

    >>> list(duplicates_justseen('mississippi'))
    ['s', 's', 'p']
    >>> list(duplicates_justseen('AaaBbbCccAaa', str.lower))
    ['a', 'a', 'b', 'b', 'c', 'c', 'a', 'a']

    This function is analogous to :func:`unique_justseen`.

    """
    def pairwise(iterable):
        a, b = tee(iterable)
        next(b, None)
        return zip(a, b)

    if key is None:
        for x, y in pairwise(iterable):
            if x == y:
                yield y
    else:
        for x, y in pairwise(iterable):
            if key(x) == key(y):
                yield y

def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    from itertools import islice, zip_longest

    def all_equal(iterable):
        a, b = islice(iterable, 2)
        return a is b and all(x == y for x, y in zip_longest(a, b))

    for prefix in zip_longest(*iterables, fillvalue=None):
        if all_equal(prefix):
            yield prefix[0]
        else:
            break

def flatten(list_of_lists):
    """Return an iterator flattening one level of nesting in a list of lists.

        >>> list(flatten([[0, 1], [2, 3]]))
        [0, 1, 2, 3]

    See also :func:`collapse`, which can flatten multiple levels of nesting.

    """
    for sublist in list_of_lists:
        for item in sublist:
            yield item

from itertools import zip_longest

def grouper(iterable, n, incomplete='fill', fillvalue=None):
    """Group elements from *iterable* into fixed-length groups of length *n*.

    >>> list(grouper('ABCDEF', 3))
    [('A', 'B', 'C'), ('D', 'E', 'F')]

    The keyword arguments *incomplete* and *fillvalue* control what happens for
    iterables whose length is not a multiple of *n*.

    When *incomplete* is `'fill'`, the last group will contain instances of
    *fillvalue*.

    >>> list(grouper('ABCDEFG', 3, incomplete='fill', fillvalue='x'))
    [('A', 'B', 'C'), ('D', 'E', 'F'), ('G', 'x', 'x')]

    When *incomplete* is `'ignore'`, the last group will not be emitted.

    >>> list(grouper('ABCDEFG', 3, incomplete='ignore', fillvalue='x'))
    [('A', 'B', 'C'), ('D', 'E', 'F')]

    When *incomplete* is `'strict'`, a `ValueError` will be raised.

    >>> iterator = grouper('ABCDEFG', 3, incomplete='strict')
    >>> list(iterator)  # doctest: +IGNORE_EXCEPTION_DETAIL
    Traceback (most recent call last):
    ...
    ValueError

    """
    if incomplete == 'fill':
        return zip_longest(*([iter(iterable)] * n), fillvalue=fillvalue)
    elif incomplete == 'ignore':
        return zip(*([iter(iterable)] * n))
    elif incomplete == 'strict':
        for element in zip(*([iter(iterable)] * n)):
            if any(x is None for x in element):
                raise ValueError("The length of the iterable is not a multiple of n")
        return zip(*([iter(iterable)] * n))
    else:
        raise ValueError("Invalid value for 'incomplete' keyword argument")
